begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
delete from public.operational_alerts;
delete from public.operational_runs;
update public.operational_monitor_state set installed_at=clock_timestamp(),checked_at=null;
select ok(not has_table_privilege('anon','public.operational_spans','SELECT'),'Las métricas no son públicas');
select ok(not has_table_privilege('authenticated','public.operational_alerts','SELECT,INSERT,UPDATE,DELETE'),'Un usuario no ve ni altera alertas de otros');
select ok(not has_function_privilege('authenticated','public.check_operational_health(integer,integer,integer)','EXECUTE'),'El monitor solo opera desde el servidor');
select ok(not has_function_privilege('anon','public.claim_operational_alerts(integer)','EXECUTE'),'El navegador no reserva notificaciones');
select ok(not (select prosecdef from pg_proc where oid='public.check_operational_health(integer,integer,integer)'::regprocedure),'El monitor no eleva privilegios');
insert into public.operational_runs(id,stage) values('00000000-0000-4000-8000-000000000066','WORKER');
select ok(public.finish_operational_run('00000000-0000-4000-8000-000000000066',true,42,
  '[{"id":"10000000-0000-4000-8000-000000000066","run_id":"00000000-0000-4000-8000-000000000066","stage":"GMAIL","outcome":"FAILED","reason_code":"UNAVAILABLE","duration_ms":42}]'),'Un fallo finaliza la ejecución y registra la etapa');
select is((select stage from public.operational_spans limit 1),'GMAIL','Se puede localizar la etapa fallida');
select is((select count(*) from public.operational_alerts where kind='IMPORTANT_FAILURE' and state='OPEN'),1::bigint,'Un fallo importante genera una alerta');
select ok(not public.finish_operational_run('00000000-0000-4000-8000-000000000066',true,42,'[]'),'Repetir el cierre no duplica métricas');
select is((select count(*) from public.operational_spans),1::bigint,'Solo hay una observación de la llamada');
select public.raise_operational_alert('IMPORTANT_FAILURE','WORKER',1,'00000000-0000-4000-8000-000000000066');
select is((select count(*) from public.operational_alerts),1::bigint,'Se deduplican los incidentes repetidos');
create temporary table claimed as select * from public.claim_operational_alerts(20);
select is((select count(*) from claimed),1::bigint,'El monitor reserva la notificación');
select is((select count(*) from public.claim_operational_alerts(20)),0::bigint,'Otro monitor no entrega el mismo incidente a la vez');
select ok(not public.finish_operational_alert_delivery((select id from claimed),gen_random_uuid(),true),'Un lease ajeno no confirma la entrega');
select ok(public.finish_operational_alert_delivery((select id from claimed),(select delivery_lease from claimed),false),'Un error de destino libera la reserva');
select is((select count(*) from public.claim_operational_alerts(20)),0::bigint,'Un fallo no produce un bucle inmediato de notificaciones');
update public.operational_alerts set next_delivery_at=clock_timestamp()-interval '1 minute';
truncate claimed;
insert into claimed select * from public.claim_operational_alerts(20);
select ok(public.finish_operational_alert_delivery((select id from claimed),(select delivery_lease from claimed),true),'Se puede confirmar un reintento posterior');
select ok((select delivered_at is not null from public.operational_alerts),'La entrega queda registrada sin guardar respuestas del webhook');
select is((select count(*) from public.claim_operational_alerts(20)),0::bigint,'Una alerta entregada respeta el periodo de silencio');
insert into public.operational_runs(id,stage) values('00000000-0000-4000-8000-000000000166','WORKER');
select ok(public.finish_operational_run('00000000-0000-4000-8000-000000000166',false,10,'[]'),'El worker se recupera');
select is((select state from public.operational_alerts where kind='IMPORTANT_FAILURE'),'RESOLVED','La recuperación resuelve el incidente');
select public.raise_operational_alert('IMPORTANT_FAILURE','WORKER',1);
select ok((select state='OPEN' and next_delivery_at<=clock_timestamp() from public.operational_alerts),'Una recaída vuelve a habilitar la notificación');
select is((public.check_operational_health()->>'workerRuns')::integer,2,'Se mide el número de ejecuciones');
select is((public.check_operational_health()->>'workerFailureRate')::numeric,0.5::numeric,'Se calcula la tasa real de fallos');
delete from public.operational_alerts;
delete from public.operational_runs;
select ok((public.check_operational_health()->>'workerFailureRate') is null,'Sin ejecuciones la tasa es desconocida');
update public.operational_monitor_state set installed_at=clock_timestamp()-interval '1 hour';
select public.check_operational_health();
select is((select count(*) from public.operational_alerts where kind='WORKER_STALLED' and state='OPEN'),1::bigint,'Se detecta un worker que nunca llegó a arrancar');
insert into public.operational_runs(id,stage,heartbeat_at) values('00000000-0000-4000-8000-000000000266','WORKER',clock_timestamp());
select public.check_operational_health();
select is((select state from public.operational_alerts where kind='WORKER_STALLED'),'RESOLVED','Un heartbeat reciente confirma la recuperación');
insert into public.operational_spans(id,run_id,stage,outcome,reason_code,duration_ms) select gen_random_uuid(),'00000000-0000-4000-8000-000000000266','OPENAI','FAILED','UNAVAILABLE',20 from generate_series(1,3);
select public.check_operational_health();
select is((select affected_count from public.operational_alerts where kind='REPEATED_ERRORS' and stage='OPENAI'),3::bigint,'Se alertan errores repetidos por proveedor');
update public.operational_spans set created_at=clock_timestamp()-interval '1 hour';
select public.check_operational_health();
select is((select state from public.operational_alerts where kind='REPEATED_ERRORS' and stage='OPENAI'),'RESOLVED','La ventana de errores no acumula incidentes para siempre');

insert into auth.users(id,aud,role,email) values('00000000-0000-4000-8000-000000000366','authenticated','authenticated','mail066@example.invalid');
\ir fixtures/privacy.inc
insert into public.gmail_accounts(id,user_id,email,status,encrypted_refresh_token,scope_set,created_at,last_sync_at)
  values('10000000-0000-4000-8000-000000000366','00000000-0000-4000-8000-000000000366','mail066@example.invalid','CONNECTED','synthetic',array['https://www.googleapis.com/auth/gmail.readonly','https://www.googleapis.com/auth/gmail.compose'],clock_timestamp()-interval '1 day',clock_timestamp()-interval '1 day');
update public.user_settings set automation_enabled=true,updated_at=clock_timestamp()-interval '1 hour' where user_id='00000000-0000-4000-8000-000000000366';
-- The settings trigger deliberately refreshes updated_at; age the test value as its owner.
alter table public.user_settings disable trigger user_settings_touch_updated_at;
update public.user_settings set updated_at=clock_timestamp()-interval '1 hour' where user_id='00000000-0000-4000-8000-000000000366';
alter table public.user_settings enable trigger user_settings_touch_updated_at;
select public.check_operational_health();
select is((select affected_count from public.operational_alerts where kind='SYNC_STALE' and state='OPEN'),1::bigint,'Se detecta la falta prolongada de sincronización');
update public.gmail_accounts set status='PAUSED' where id='10000000-0000-4000-8000-000000000366';
select public.check_operational_health();
select is((select state from public.operational_alerts where kind='SYNC_STALE'),'RESOLVED','Una cuenta pausada no produce falsas alarmas de sincronización');
update public.gmail_accounts set status='CONNECTED' where id='10000000-0000-4000-8000-000000000366';
insert into public.email_jobs(user_id,gmail_account_id,thread_id,target_message_id)
  values('00000000-0000-4000-8000-000000000366','10000000-0000-4000-8000-000000000366','synthetic-thread','synthetic-message');
select count(*) from public.claim_email_job(300,false);
update public.email_jobs set lease_expires_at=clock_timestamp()-interval '10 minutes' where user_id='00000000-0000-4000-8000-000000000366';
select public.check_operational_health();
select is((select affected_count from public.operational_alerts where kind='JOB_STALLED' and state='OPEN'),1::bigint,'Detecta trabajos bloqueados con lease vencido');
update public.email_jobs set lease_expires_at=clock_timestamp()+interval '5 minutes' where user_id='00000000-0000-4000-8000-000000000366';
select public.check_operational_health();
select is((select state from public.operational_alerts where kind='JOB_STALLED'),'RESOLVED','Un trabajo recuperado deja de considerarse bloqueado');
insert into public.operational_runs(id,stage,status,finished_at) select gen_random_uuid(),'WORKER','FAILED',clock_timestamp() from generate_series(1,5);
select public.check_operational_health();
select is((select affected_count from public.operational_alerts where kind='WORKER_FAILURE_RATE' and state='OPEN'),5::bigint,'Se alerta una tasa elevada de fallos del worker');
insert into public.operational_runs(id,stage,started_at) values('00000000-0000-4000-8000-000000000466','WEB',clock_timestamp()-interval '30 days');
select public.purge_operational_telemetry(14);
select is((select count(*) from public.operational_runs where id='00000000-0000-4000-8000-000000000466'),0::bigint,'Se limita la conservación de telemetría');
select throws_ok($$select public.purge_operational_telemetry(1)$$,'P0001','INVALID_INPUT','No acepta plazos de conservación inválidos');
select throws_ok($$select public.claim_operational_alerts(1000)$$,'P0001','INVALID_INPUT','La entrega tiene límites de lote');
select throws_ok($$select public.check_operational_health(1,900,3)$$,'P0001','INVALID_INPUT','La ventana de monitorización se valida');
select throws_ok($$select public.finish_operational_run('00000000-0000-4000-8000-000000000266',false,1,'[{"run_id":"00000000-0000-4000-8000-000000000266","body":"private email"}]')$$,'P0001','INVALID_INPUT','El esquema rechaza contenido arbitrario');
select * from finish();
rollback;
